// Auth + validation du brief (cf skills/site-builder.md).
const h = $json.headers || {};
const token = h['x-symbalyx-token'] || h['X-Symbalyx-Token'] || '';
const expected = $env.SYMBALYX_WEBHOOK_SECRET || '';
if (!expected) return [{ json: { _ok:false, _status:500, _error:'SYMBALYX_WEBHOOK_SECRET not configured' } }];
if (token !== expected) return [{ json: { _ok:false, _status:401, _error:'invalid_token' } }];
const b = $json.body || {};
const project_id = String(b.project_id || '').trim();
const client_name = String(b.client_name || '').trim();
const niche = String(b.niche || '').trim();
const city = String(b.city || '').trim();
const tone = String(b.tone || 'élégant').trim();
const colors = String(b.colors || 'sobre, contraste fort').trim();
const pages = Array.isArray(b.pages) ? b.pages : ['home','services','contact'];
if (!project_id || !client_name || !niche) {
  return [{ json: { _ok:false, _status:400, _error:'missing project_id, client_name or niche' } }];
}
const userPrompt = `Client : ${client_name}\nNiche : ${niche}\nVille : ${city || 'France'}\nTone : ${tone}\nCouleurs : ${colors}\nPages demandées : ${pages.join(', ')}\nEmail contact : ${b.email || '(à demander au client)'}\nTéléphone : ${b.phone || '(à demander)'}\nHoraires : ${b.hours || '(non précisé)'}\nBrief libre : ${b.brief_summary || ''}\n\nGénère index.html complet, autonome, en français, mobile-first.`;
return [{ json: { _ok:true, project_id, client_name, niche, city, tone, colors, pages, email: b.email||'', phone: b.phone||'', hours: b.hours||'', brief_summary: b.brief_summary||'', userPrompt } }];

// Extrait le HTML de la réponse Claude + valide.
const resp = $json;
const content = (resp.content || []).find(c => c.type === 'text');
let html = (content && content.text) || '';
// Strip code fences si Claude en a mis quand même
html = html.replace(/^```(?:html)?\s*/i, '').replace(/```\s*$/i, '').trim();
const inp = $('Auth & validate brief').first().json;

// Validation
const checks = {
  starts_with_html: /^<!doctype html|^<html/i.test(html),
  has_title: /<title>[^<]+<\/title>/i.test(html),
  has_tailwind: /cdn\.tailwindcss\.com/.test(html),
  has_client_name: html.toLowerCase().includes(inp.client_name.toLowerCase()),
  ends_with_html: /<\/html>\s*$/.test(html),
  size_ok: html.length > 3000 && html.length < 200000
};
const ok = Object.values(checks).every(Boolean);

const version = Date.now();
const deliverable_id = 'del_' + version;
const usage = resp.usage || {};
const cost_eur = ((usage.input_tokens||0) * 0.000015 + (usage.output_tokens||0) * 0.000075).toFixed(4);

return [{ json: {
  _ok: ok,
  _status: ok ? 200 : 422,
  _error: ok ? '' : ('html validation failed: ' + JSON.stringify(checks)),
  html,
  html_size: html.length,
  checks,
  deliverable_id,
  project_id: inp.project_id,
  client_name: inp.client_name,
  niche: inp.niche,
  generated_by: 'WF50 / claude-opus-4-7',
  cost_eur,
  input_tokens: usage.input_tokens || 0,
  output_tokens: usage.output_tokens || 0
} }];
